function rollPotionReward(r,random=Math.random){const rate=Number.isFinite(r.potionDropRate)?Math.max(0,Math.min(100,r.potionDropRate)):50;const chance=Math.min(100,rate+(r.kind==='elite'?30:0));if(random()*100<chance){r.potionDropRate=Math.max(0,rate-15);return rand(POTIONS).id;}r.potionDropRate=Math.min(100,rate+5);return null;}
const potionVictoryBase=victory;victory=function(){const r=S.run;if(r?.mode==='battle'&&!r.battleRelicGranted&&['fight','elite'].includes(r.kind)){r.rewardPotion=rollPotionReward(r);r.rewardPotionClaimed=false;}r.rewardRevealSeen=false;return potionVictoryBase();};
function claimRewardPotion(){const r=S.run;if(!r||page!=='reward'||r.mode!=='reward'||!r.rewardPotion||r.rewardPotionClaimed||busy)return;if(hasRelic('energy_potions',r)){toast('遺物の効果でポーションを所持できません');return;}if((r.potions||[]).length>=2){const btn=document.querySelector('.reward-potion'),belt=document.querySelector('.potion-belt');for(const [el,cls] of [[btn,'potion-shake'],[belt,'potion-full-alert']])if(el){el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls);setTimeout(()=>el.classList.remove(cls),1500);}return;}r.potions??=[];r.potions.push(r.rewardPotion);r.rewardPotionClaimed=true;render();}
const potionRewardBase=reward;reward=function(){const r=S.run;let html=potionRewardBase(),alreadyRevealed=!!r.rewardRevealSeen,gold=r.kind==='elite'?40:r.kind==='boss'?60:20,packs=r.kind==='boss'?3:1;const icons='<div class="chest-extra reward-loot"><strong>◈ '+gold+'</strong><strong>▣ ×'+packs+'</strong></div>';html=html.replace(/<p>(?:3パック・60金|1パック・(?:20|40)金)を獲得。<\/p>/,icons);if(alreadyRevealed)html=html.replace('class="reward"','class="reward reward-revealed"');r.rewardRevealSeen=true;const p=POTIONS.find(x=>x.id===r.rewardPotion),button=p?'<div class="reward-potion-row"><button class="reward-potion" onclick="claimRewardPotion()" '+(r.rewardPotionClaimed?'disabled':'')+'>'+p.icon+'<span>'+p.name+'</span><small>'+(r.rewardPotionClaimed?'受取済み':'受け取る')+'</small></button></div>':'';return html.replace(icons,icons+button);};
let potionMenuIndex=null;
function openPotionMenu(i){const r=S.run;if(!r||page!==r.mode||busy||r.pendingChoice||r.hunterChoice||r.pendingDiscard||r.potionTarget!=null||r.lucky?.choice||r.lucky?.queue?.length||!r.potions?.[i])return;potionMenuIndex=potionMenuIndex===i?null:i;render();}
function usePotionMenu(i){if(potionMenuIndex!==i)return;potionMenuIndex=null;usePotion(i);}
function discardPotionMenu(i){const r=S.run;if(potionMenuIndex!==i||!r||page!==r.mode||busy||r.pendingChoice||r.hunterChoice||r.pendingDiscard||r.potionTarget!=null||r.lucky?.choice||r.lucky?.queue?.length||!r.potions?.[i])return;r.potions.splice(i,1);potionMenuIndex=null;render();}
function closePotionMenu(){potionMenuIndex=null;render();}
potionBelt=function(){const r=S.run;if(!r)return '';return '<section class="potion-belt" aria-label="消費アイテム"><b>消費アイテム '+(r.potions?.length||0)+' / 2</b>'+(r.potions||[]).map((id,i)=>{const p=POTIONS.find(x=>x.id===id);if(!p)return '';const menu=potionMenuIndex===i?'<div class="potion-menu"><strong>'+p.name+'</strong><p>'+p.desc+'</p><button onclick="usePotionMenu('+i+')" '+(canUsePotion(p)?'':'disabled')+'>使用</button><button onclick="discardPotionMenu('+i+')">捨てる</button><button onclick="closePotionMenu()">閉じる</button></div>':'';return '<span class="potion-slot"><button onclick="openPotionMenu('+i+')" aria-label="'+p.name+'の操作">'+p.icon+' '+p.name+'</button><aside class="tooltip"><strong>'+p.name+'</strong><p>'+p.desc+'</p></aside>'+menu+'</span>';}).join('')+Array.from({length:Math.max(0,2-(r.potions?.length||0))},()=>'<span class="potion-empty">空き</span>').join('')+(r.potionTarget!=null?'<strong class="potion-target-label">対象の敵を選択</strong><button onclick="cancelPotionTarget()">キャンセル</button>':'')+'</section>';};
function resetRelicSearch(){relicSearch='';relicEffectFilter=[];relicFavoriteOnly=false;render();}
const potionRenderBase=render;render=function(){potionRenderBase();};
if(!globalThis.ASHBOUND_HEADLESS)render();
